import React, { useState, useEffect, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import Editor from '@monaco-editor/react';
import { Terminal } from 'xterm';
import 'xterm/css/xterm.css';
import '../css/Projectpage.css';

export default function ProjectPage() {
    const navigate = useNavigate();
    const [files, setFiles] = useState([]);
    const [activeIndex, setActiveIndex] = useState(null);
    const [activeTab, setActiveTab] = useState('console'); // 'console' or 'shell'
    const termRef = useRef(null);
    const xtermRef = useRef(null);
    const editorRef = useRef(null);

    useEffect(() => {
        // Initialize xterm terminal
        xtermRef.current = new Terminal({ convertEol: true });
        xtermRef.current.open(termRef.current);
        xtermRef.current.writeln('Ready.');

        // Redirect console.log to xterm
        const originalLog = console.log;
        console.log = (...args) => {
            xtermRef.current.writeln(args.join(' '));
            originalLog(...args);
        };
        return () => {
            console.log = originalLog;
        };
    }, []);

    // Navigate back
    const handleBack = () => navigate(-1);

    // Create new file
    const handleNewFile = () => {
        const fileName = prompt('새 파일 이름을 입력하세요 (확장자 포함):');
        if (!fileName) return;
        if (files.find(f => f.name === fileName)) {
            alert('이미 동일한 이름의 파일이 존재합니다.');
            return;
        }
        setFiles(prev => {
            const newFiles = [...prev, { name: fileName, content: '' }];
            setActiveIndex(newFiles.length - 1);
            return newFiles;
        });
    };

    // Drop files
    const handleFileDrop = e => {
        e.preventDefault();
        const dropped = Array.from(e.dataTransfer.files);
        dropped.forEach(file => {
            const reader = new FileReader();
            reader.onload = () => {
                setFiles(prev => {
                    const next = [...prev, { name: file.name, content: reader.result }];
                    setActiveIndex(next.length - 1);
                    return next;
                });
            };
            reader.readAsText(file);
        });
    };
    const handleDragOver = e => e.preventDefault();

    // Select a file to edit
    const handleSelectFile = idx => setActiveIndex(idx);

    // Editor mount
    const handleEditorDidMount = editor => {
        editorRef.current = editor;
    };

    // Run code
    const runCode = () => {
        if (!editorRef.current) return;
        const code = editorRef.current.getValue();
        xtermRef.current.clear();
        try {
            // eslint-disable-next-line no-eval
            eval(code);
        } catch (err) {
            xtermRef.current.writeln(err.toString());
        }
    };

    return (
        <div className="ide-container three-pane">
            <header className="ide-header">
                <button className="ide-back-btn" onClick={handleBack}>&larr; 뒤로</button>
                <h2>프로젝트</h2>
                <button className="new-file-btn" onClick={handleNewFile}>새 파일</button>
            </header>

            <div className="ide-body">
                {/* Left: File Tree */}
                <aside className="file-tree" onDrop={handleFileDrop} onDragOver={handleDragOver}>
                    {files.map((f, i) => (
                        <div
                            key={i}
                            className={`file-item ${activeIndex === i ? 'active' : ''}`}
                            onClick={() => handleSelectFile(i)}
                        >{f.name}</div>
                    ))}
                    <div className="file-item placeholder">여기에 드래그하세요</div>
                </aside>

                {/* Center: Editor */}
                <div className="editor-pane">
                    <Editor
                        height="100%"
                        language="javascript"
                        value={files[activeIndex]?.content || ''}
                        onMount={handleEditorDidMount}
                        onChange={val => {
                            if (activeIndex === null) return;
                            setFiles(prev => {
                                const arr = [...prev];
                                arr[activeIndex] = { ...arr[activeIndex], content: val || '' };
                                return arr;
                            });
                        }}
                        theme="vs-dark"
                    />
                    <button className="run-btn" onClick={runCode}>Run</button>
                </div>

                {/* Right: Console/Shell */}
                <div className="console-pane three-pane-right">
                    <div className="console-header">
                        <div
                            className={`tab ${activeTab === 'console' ? 'active' : ''}`}
                            onClick={() => setActiveTab('console')}
                        >Console</div>
                        <div
                            className={`tab ${activeTab === 'shell' ? 'active' : ''}`}
                            onClick={() => setActiveTab('shell')}
                        >Shell</div>
                    </div>
                    <div className="console-body">
                        {activeTab === 'console' && <div ref={termRef} className="terminal" />}
                        {activeTab === 'shell' && (
                            <div className="shell-placeholder">Shell 모드(구현 예정)</div>
                        )}
                    </div>
                </div>
            </div>
        </div>
    );
}
